'use strict';

// MODULES //

var tape = require( 'tape' );
var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
var pluck = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof pluck, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function extracts property values from an input object array and assigns results to elements in a new output array', function test( t ) {
	var expected;
	var actual;
	var x;

	x = [
		{
			'a': 1
		},
		{
			'a': 2
		},
		{
			'a': 3
		}
	];
	expected = [ 1, 2, 3 ];
	actual = pluck( x, 'a' );

	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function skips undefined and null array elements', function test( t ) {
	var expected;
	var actual;
	var x;

	x = [
		{
			'a': 1
		},
		void 0,
		{
			'a': 3
		},
		null,
		{
			'a': 5
		}
	];
	expected = [ 1, , 3, , 5 ]; // eslint-disable-line no-sparse-arrays
	actual = pluck( x, 'a' );

	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function extracts property values from an input object array and assigns results to elements in an output array', function test( t ) {
	var expected;
	var actual;
	var x;

	x = [
		{
			'a': 1
		},
		{
			'a': 2
		},
		{
			'a': 3
		}
	];
	expected = [ 1, 2, 3 ];
	actual = pluck( toAccessorArray( x ), 'a' );

	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});
